import{_ as s,a0 as l,w as i,s as p,I as r,x as o,a1 as a,A as e,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"書評：《Ours to Hack and to Own》 | LCTT x X-CMD","titleTemplate":false,"description":"書評：《Ours to Hack and to Own》 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"書評：《Ours to Hack and to Own》 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"書評：《Ours to Hack and to Own》 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170131 Book review Ours to Hack and to Own","title":"書評：《Ours to Hack and to Own》","tag":"201801","desc":""},"relativePath":"201801/20170131 Book review Ours to Hack and to Own.md","filePath":"[post].md"}'),d={name:"201801/20170131 Book review Ours to Hack and to Own.md"};function k(w,t,m,O,f,b){const n=l("Link");return i(),p("div",null,[t[22]||(t[22]=r("h1",{id:"書評-《ours-to-hack-and-to-own》",tabindex:"-1"},[o("書評：《Ours to Hack and to Own》 "),r("a",{class:"header-anchor",href:"#書評-《ours-to-hack-and-to-own》","aria-label":"Permalink to “書評：《Ours to Hack and to Own》”"},"​")],-1)),t[23]||(t[23]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDUCATION_colorbooks.png?itok=vNhsYYyC",alt:"書評: Ours to Hack and to Own",title:"Book review: Ours to Hack and to Own"})],-1)),t[24]||(t[24]=r("p",null,"Image by : opensource.com",-1)),t[25]||(t[25]=r("p",null,"私有制的時代看起來似乎結束了，在這裏我將不僅僅討論那些由我們中的許多人引入到我們的家庭與生活的設備和軟件，我也將討論這些設備與應用依賴的平台與服務。",-1)),r("p",null,[t[1]||(t[1]=o("儘管我們使用的許多服務是免費的，但我們對它們並沒有任何控制權。本質上講，這些企業確實控制着我們所看到的、聽到的以及閲讀到的內容。不僅如此，許多企業還在改變工作的本質。他們正使用封閉的平台來助長由全職工作到",-1)),a(n,{href:"https://en.wikipedia.org/wiki/Access_economy"},{default:e(()=>[...t[0]||(t[0]=[o("零工經濟",-1)])]),_:1}),t[2]||(t[2]=o("的轉變，這種方式提供極少的安全性與確定性。",-1))]),t[26]||(t[26]=r("p",null,"這項行動對於網絡以及每一個使用與依賴網絡的人產生了廣泛的影響。僅僅二十多年前的對開放互聯網的想像正在逐漸消逝，並迅速地被一塊難以穿透的幕簾所取代。",-1)),r("p",null,[t[6]||(t[6]=o("一種逐漸流行的補救辦法就是建立",-1)),r("ruby",null,[a(n,{href:"https://en.wikipedia.org/wiki/Platform_cooperative"},{default:e(()=>[...t[3]||(t[3]=[o("平台合作社",-1)])]),_:1}),t[4]||(t[4]=r("rt",null,"platform cooperatives",-1))]),t[7]||(t[7]=o("， 即由他們的用户所擁有的電子化平台。正如這本書",-1)),a(n,{href:"http://www.orbooks.com/catalog/ours-to-hack-and-to-own/"},{default:e(()=>[...t[5]||(t[5]=[o("《Ours to Hack and to Own》",-1)])]),_:1}),t[8]||(t[8]=o("所闡述的，平台合作社背後的觀點與開源有許多相同的根源。",-1))]),t[27]||(t[27]=u('<p>學者 Trebor Scholz 和作家 Nathan Schneider 已經收集了 40 篇論文，探討平台合作社作為普通人可使用的工具的增長及需求，以提升開放性並對閉源系統的不透明性及各種限制予以還擊。</p><h3 id="何處適合開源" tabindex="-1">何處適合開源 <a class="header-anchor" href="#何處適合開源" aria-label="Permalink to “何處適合開源”">​</a></h3><p>任何平台合作社核心及接近核心的部分依賴於開源；不僅開源技術是必要的，構成開源開放性、透明性、協同合作以及共享的準則與理念同樣不可或缺。</p><p>在這本書的介紹中，Trebor Scholz 指出：</p><blockquote><p>與斯諾登時代的互聯網黑盒子系統相反，這些平台需要使它們的數據流透明來辨別自身。他們需要展示客户與員工的數據在哪裏存儲，數據出售給了誰以及數據用於何種目的。</p></blockquote><p>正是對開源如此重要的透明性，促使平台合作社如此吸引人，並在目前大量已有平台之中成為令人耳目一新的變化。</p><p>開源軟件在《Ours to Hack and to Own》所分享的平台合作社的構想中必然充當着重要角色。開源軟件能夠為羣體建立助推合作社的技術基礎設施提供快速而不算昂貴的途徑。</p><p>Mickey Metts 在論文中這樣形容， “邂逅你的友鄰技術夥伴。&quot; Metts 為一家名為 Agaric 的企業工作，這家企業使用 Drupal 為團體及小型企業建立他們不能自行完成的平台。除此以外, Metts 還鼓勵任何想要建立並運營自己的企業的公司或合作社的人接受自由開源軟件。為什麼呢？因為它是高質量的、並不昂貴的、可定製的，並且你能夠與由樂於助人而又熱情的人們組成的大型社區產生聯繫。</p><h3 id="不總是開源的-但開源總在" tabindex="-1">不總是開源的，但開源總在 <a class="header-anchor" href="#不總是開源的-但開源總在" aria-label="Permalink to “不總是開源的，但開源總在”">​</a></h3><p>這本書裏不是所有的論文都關注或提及開源的；但是，開源方式的關鍵元素——合作、社區、開放治理以及電子自由化——總是在其間若隱若現。</p><p>事實上正如《Ours to Hack and to Own》中許多論文所討論的，建立一個更加開放、基於平常人的經濟與社會區塊，平台合作社會變得非常重要。用 Douglas Rushkoff 的話講，那會是類似 Creative Commons 的組織“對共享知識資源的私有化”的補償。它們也如 Barcelona 的 CTO Francesca Bria 所描述的那樣，是“通過確保市民數據安全性、隱私性和權利的系統”來運營他們自己的“分佈式通用數據基礎架構”的城市。</p><h3 id="最後的思考" tabindex="-1">最後的思考 <a class="header-anchor" href="#最後的思考" aria-label="Permalink to “最後的思考”">​</a></h3><p>如果你在尋找改變互聯網以及我們工作的方式的藍圖，《Ours to Hack and to Own》並不是你要尋找的。這本書與其説是用户指南，不如説是一種宣言。如書中所説，《Ours to Hack and to Own》讓我們略微瞭解如果我們將開源方式準則應用於社會及更加廣泛的世界我們能夠做的事。</p><hr><p>作者簡介:</p><p>Scott Nesbitt ——作家、編輯、僱傭兵、 <ruby>虎貓牛仔<rt>Ocelot wrangle</rt></ruby>、丈夫與父親、Blog寫手、陶器收藏家。Scott 正是做這樣的一些事情。他還是大量寫關於開源軟件文章與Blog的長期開源用户。你可以在 Twitter、Github 上找到他。</p><hr>',17)),r("p",null,[t[10]||(t[10]=o("via: ",-1)),a(n,{href:"https://opensource.com/article/17/1/review-book-ours-to-hack-and-own"},{default:e(()=>[...t[9]||(t[9]=[o("https://opensource.com/article/17/1/review-book-ours-to-hack-and-own",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=o("作者：",-1)),a(n,{href:"https://opensource.com/users/scottnesbitt"},{default:e(()=>[...t[11]||(t[11]=[o("Scott Nesbitt",-1)])]),_:1}),t[15]||(t[15]=o(" 譯者：",-1)),a(n,{href:"https://github.com/darsh8"},{default:e(()=>[...t[12]||(t[12]=[o("darsh8",-1)])]),_:1}),t[16]||(t[16]=o(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[19]||(t[19]=o("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[17]||(t[17]=[o("LCTT",-1)])]),_:1}),t[20]||(t[20]=o(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:e(()=>[...t[18]||(t[18]=[o("Linux中國",-1)])]),_:1}),t[21]||(t[21]=o(" 榮譽推出",-1))])])}const H=s(d,[["render",k]]);export{C as __pageData,H as default};
